(()=>{const assets={"base.png":"data:image/png;base64,","range.png":"data:image/png;base64,","hole0.png":"data:image/png;base64,","room.png":"data:image/png;base64,","barrel.png":"data:image/png;base64,","table.png":"data:image/png;base64,","hole6.png":"data:image/png;base64,","flash.png":"data:image/png;base64,","shot-single.mp3":"data:audio/mpeg;base64,","hole2.png":"data:image/png;base64,","hole3.png":"data:image/png;base64,","guard.png":"data:image/png;base64,","reload.mp3":"data:audio/mpeg;base64,","sanguis.png":"data:image/png;base64,","hole4.png":"data:image/png;base64,","hole8.png":"data:image/png;base64,","hole1.png":"data:image/png;base64,","hole5.png":"data:image/png;base64,","hole7.png":"data:image/png;base64,"};Object.assign(assets,{"dennis-front.png": "data:image/png;base64,", "dennis-side.png": "data:image/png;base64,"});const style=document.createElement('style');style.textContent=`.cgr .cgr-dennis{position:absolute!important;left:4%;top:16%;height:66%;width:24%;z-index:2;background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important;cursor:pointer}.cgr .cgr-dennis-img{inset:0;width:100%;height:100%;object-fit:contain}.cgr .cgr-dialog{position:absolute;left:29%;top:15%;width: min(58%, 520px);max-height:78%;overflow:auto;box-sizing:border-box;z-index:5;background:rgba(20,20,20,.95);color:white;padding:clamp(8px,1.5vw,14px);border-left:3px solid #F0003C;border-radius:6px;margin:0;font-size:clamp(12px,1.6vw,16px)}.cgr-dialog[hidden]{display:none!important}.cgr-dialog-head{display:flex;justify-content:space-between;align-items:center;color:#F0003C;font-weight:bold;letter-spacing:.12em}.cgr-dialog-line{min-height:3em;padding:12px 0;line-height:1.6;white-space:pre-wrap}.cgr-dialog-choices{display:grid;grid-template-columns:1fr;gap:6px}.cgr-dialog-choices .cgr-btn{text-align:left;white-space:normal;overflow-wrap:anywhere;min-width:0}.cgr-dialog-head .cgr-btn{flex:none}.cgr-dialog-line{overflow-wrap:anywhere}`;document.head.append(style);let dispose=()=>{};window.custiaGuardStop=()=>dispose();window.custiaGuardDraw=(host)=>{dispose();const root=document.createElement('section');root.className='cgr';host.append(root);let alive=true,seq=0,timers=[],audio=[];const bgm=new Audio('data:audio/mpeg;base64,');bgm.loop=true;bgm.volume=0;let fade=0,wanted=false;const fadeTo=(v,done)=>{clearInterval(fade);const start=bgm.volume,t=performance.now();fade=setInterval(()=>{const f=Math.min(1,(performance.now()-t)/450);bgm.volume=start+(v-start)*f;if(f===1){clearInterval(fade);done?.()}},30)};const startMusic=()=>{wanted=true;bgm.play().then(()=>{if(wanted&&alive&&root.isConnected)fadeTo(.25);else bgm.pause()}).catch(()=>{})};const stopMusic=()=>{wanted=false;fadeTo(0,()=>{if(!wanted)bgm.pause()})};const retry=()=>{if(wanted&&bgm.paused)startMusic()};root.addEventListener('pointerdown',retry);root.addEventListener('click',retry);const observer=new MutationObserver(()=>{if(!root.isConnected){stopMusic();observer.disconnect()}});observer.observe(document.body,{childList:true,subtree:true});const stop=()=>{timers.forEach(clearTimeout);timers=[];audio.forEach(a=>{a.pause();a.currentTime=0});audio=[]};dispose=()=>{alive=false;seq++;stop();stopMusic();observer.disconnect()};const later=(f,t)=>timers.push(setTimeout(()=>{if(alive&&root.isConnected)f()},t));const el=(tag,cls,parent)=>{const e=document.createElement(tag);e.className=cls;parent.append(e);return e};const img=(name,cls,parent)=>{const e=el('img',cls,parent);e.src=assets[name+'.png'];e.alt='';e.draggable=false;return e};const btn=(label,parent,fn)=>{const b=el('button','cgr-btn',parent);b.type='button';b.textContent=label;b.onclick=fn;return b};const play=(name)=>{const a=new Audio(assets[name+'.mp3']);audio.push(a);a.onended=()=>{audio=audio.filter(x=>x!==a)};a.play().catch(()=>{audio=audio.filter(x=>x!==a)})};
function dennis(stage){
 const npc=btn('',stage,begin);npc.className='cgr-dennis';npc.setAttribute('aria-label','Talk to Dennis');const portrait=img('dennis-side','cgr-dennis-img',npc);const preload=new Image();preload.src=assets['dennis-front.png'];
 const panel=el('div','cgr-dialog',stage);panel.hidden=true;const header=el('div','cgr-dialog-head',panel);header.textContent='DENNIS';btn('×',header,close);const line=el('div','cgr-dialog-line',panel);line.setAttribute('aria-live','polite');const choices=el('div','cgr-dialog-choices',panel);let turn=0,busy=false,script=null;
 const scripts={Prisoner:['แกเข้ามาได้ยังไงเนี้ย...เห้อ แต่ก็เอาเถอะ ต้องการอะไร?',[['ขอปืนหน่อย','แกอยากตายหรอ? ฉันสามารถช็อตแกให้ชักตายตรงนี้ได้เลยนะ'],['ฉันกลัวกอดฉันหน่อย','แกเป็นบ้าอะไร?'],['ห้องน้ำอยู่ไหน','คำถามที่ดีกว่าคือแกเข้ามาในห้องนี้ได้ยังไง มั้งๆที่ชักโครกก็อยู่ในห้องขังอยู่แล้ว'],['ลาก่อน','บาย',true]]],Teacher:['ว่าไง อาจาร์ย สอนเสร็จแล้วหรอ?',[['ขอปืนหน่อย','ก็มีของคุณครูไม่ใช่หรอ?'],['อยากยิงปืนเล่น','ข้างหน้านั้นเลย'],['ห้องน้ำอยู่ไหน','มือใหม่หรอครัยคุณครู? ห้องน้ำอยู่ทางซ้าย'],['ลาก่อน','ครับไปดีครับคุณครู',true]]],Guard:['เฮ้ เฮ้ ว่าไง~',[['นายชื่ออะไรนะ','ฉัน Dennis ไง จำไม่ได้หรอ?'],['ขอยิงปืนหน่อย','เค แต่จ่ายมา 2 คัสเตียด้วย กระสุนไม่ใช่ว่าจะยิงได้ฟรีๆ'],['ฉันหลงทาง','ยินดีด้วย'],['มีนักโทษแหกคุก','ห้ะ! ที่ไหน! ฉันจะรีบไปเดี๋ยวนี้แหละ!']]]};
 function face(front){portrait.src=assets[(front?'dennis-front':'dennis-side')+'.png']}
 function close(){turn++;busy=false;panel.hidden=true;face(false);choices.replaceChildren()}
 function menu(){choices.replaceChildren();for(const [q,a,end] of script[1])btn(q,choices,()=>speak(a,()=>{if(end)btn('ปิดบทสนทนา',choices,close);else menu()}))}
 function speak(text,done){const t=++turn;busy=true;face(true);choices.replaceChildren();line.textContent='';let i=0;const chars=typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter('th',{granularity:'grapheme'}).segment(text),x=>x.segment):Array.from(text);function tick(){if(t!==turn||!panel.isConnected)return;line.textContent+=chars[i++]||'';if(i<chars.length)later(tick,32);else{busy=false;face(false);done()}}tick()}
 async function begin(){if(busy||!panel.hidden)return;panel.hidden=false;busy=true;line.textContent='…';const t=++turn;let role='Guest';try{const db=window.custia093db;const s=await db.auth.getSession();if(s.error)throw s.error;if(s.data.session){const q=await db.rpc('custia_staff_role');if(q.error)throw q.error;role=q.data||'Prisoner'}}catch(e){if(t===turn&&panel.isConnected){busy=false;line.textContent='Could not verify role.'}return}if(t!==turn||!panel.isConnected)return;script=scripts[role];if(!script){busy=false;line.textContent='ยังไม่มีบทสนทนาสำหรับตำแหน่งนี้';return}speak(script[0],menu)}
}
function room(){seq++;stop();root.replaceChildren();const title=el('h3','cgr-title',root);title.textContent='GUARD ROOM';const stage=el('div','cgr-stage cgr-room',root);img('room','cgr-bg',stage);const b=btn('Shooting Range',stage,range);b.className='cgr-entry';b.setAttribute('aria-label','Enter shooting range');dennis(stage);startMusic()}
async function range(){const token=++seq;stopMusic();stop();root.replaceChildren();const bar=el('div','cgr-bar',root);btn('← Guard Room',bar,room);const status=el('span','cgr-status',bar);status.textContent='Loading target…';const stage=el('div','cgr-stage cgr-range',root);img('range','cgr-bg',stage);let role='Guest';try{const db=window.custia093db;if(!db)throw Error('Session unavailable');const s=await db.auth.getSession();if(s.error)throw s.error;if(s.data.session){const q=await db.rpc('custia_staff_role');if(q.error)throw q.error;role=q.data||'Prisoner'}}catch(e){if(alive&&token===seq)status.textContent='Could not verify role. Return and retry.';return}if(!alive||token!==seq||!root.isConnected)return;img(role==='Prisoner'?'guard':'sanguis','cgr-target',stage);const holes=el('div','cgr-holes',stage);img('table','cgr-table',stage);const barrel=img('barrel','cgr-barrel',stage);img('base','cgr-base',stage);const flash=img('flash','cgr-flash',stage);flash.hidden=true;const controls=el('div','cgr-bar',root);let ammo=10,reloading=false,flashTimer=0;const count=el('strong','cgr-count',controls);const reload=btn('RELOAD',controls,()=>{if(reloading||ammo===10)return;reloading=true;play('reload');update();later(()=>{ammo=10;reloading=false;update()},1512)});btn('RESET TARGET',controls,()=>holes.replaceChildren());function update(){count.textContent=String(ammo).padStart(2,'0')+' / 10';reload.disabled=reloading||ammo===10;status.textContent=reloading?'RELOADING…':ammo===0?'RELOAD REQUIRED':'SHOOTING RANGE'}update();function aim(e){const r=stage.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;const angle=Math.atan2((x-.48)*r.width,(.84-y)*r.height)*180/Math.PI;barrel.style.transform=`translateX(-50%) rotate(${angle}deg)`;return {x,y,angle}}stage.addEventListener('pointermove',aim);stage.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;e.preventDefault();const p=aim(e);if(reloading||ammo<=0)return;ammo--;update();play('shot-single');const h=img('hole'+Math.floor(Math.random()*9),'cgr-hole',holes);h.style.left=p.x*100+'%';h.style.top=p.y*100+'%';if(holes.children.length>300)holes.firstChild.remove();const r=stage.getBoundingClientRect(),rad=p.angle*Math.PI/180;flash.style.left=(48+Math.sin(rad)*r.height/r.width*30)+'%';flash.style.top=(84-Math.cos(rad)*30)+'%';flash.hidden=false;clearTimeout(flashTimer);flashTimer=setTimeout(()=>flash.hidden=true,85);});}room()}})();
